<script>
 import {onDestroy,untrack} from 'svelte';import {LoaderCircle,AlertCircle,Scissors,FileText} from 'lucide-svelte';import {loadTileThumbnail} from '../services/library.js';import {studio} from '../studio.svelte';
 let {asset,selected=false,size=160,list=false,onclick=()=>{},onopen=()=>{},onmenu=()=>{},onloaded=()=>{}}=$props();let url=$state(''),error=$state(''),attempt=$state(0),epoch=0;
 const cutout=$derived(asset.cutout===true||asset.versions?.some(v=>v.generation?.operations?.some(op=>op.kind==='cutout'))),described=$derived(asset.descriptionStatus==='done'||!!asset.description);
 $effect(()=>{const fingerprint=JSON.stringify([asset.sha256,asset.generatedBase,asset.edit,size]);void fingerprint;attempt;const token=++epoch;error='';const oldUrl=untrack(()=>url);if(oldUrl){URL.revokeObjectURL(oldUrl);url='';}loadTileThumbnail(asset,size).then(value=>{if(token!==epoch){if(value)URL.revokeObjectURL(value);return;}if(!value){error='当前模式未生成缩略图';return;}if(url)URL.revokeObjectURL(url);url=value;onloaded(asset.id);}).catch(e=>{if(token===epoch)error=e.message;});return()=>{epoch++;};});
 onDestroy(()=>{if(url)URL.revokeObjectURL(url);});
</script>
<div class="asset-tile-container"><button class="asset-tile" class:selected class:list role="option" aria-selected={selected} aria-label={asset.name} onclick={event=>onclick(event,asset.id)} ondblclick={()=>onopen(asset.id)} oncontextmenu={event=>{event.preventDefault();onmenu(event,asset.id);}} data-asset-id={asset.id} title={error||asset.name}>
 <div class="asset-image">{#if url}<img src={url} alt="" draggable="false"/>{:else if error}<span class="tile-error"><AlertCircle size={20}/>缩略图失败</span>{:else}<span class="tile-loading" aria-label="加载缩略图"></span>{/if}
 {#if asset.processingStatus==='running'||asset.processingStatus==='queued'}<span class="tile-status" aria-label="正在处理"><LoaderCircle size={16}/></span>{:else if asset.processingStatus==='failed'}<span class="tile-status failed" aria-label="处理失败"><AlertCircle size={16}/></span>{/if}
 {#if (asset.versions?.length||0)>0}<span class="tile-versions">{asset.versions.length+1}</span>{/if}<span class="tile-tags">{#if cutout}<Scissors size={12}/>{/if}{#if described}<FileText size={12}/>{/if}</span>
 </div><span class="tile-name">{asset.name}</span>{#if list}<small>{asset.width} × {asset.height}</small>{/if}
</button>
{#if error}<button class="tile-retry" aria-label={`重新加载 ${asset.name} 的缩略图`} title={error} onpointerdown={event=>event.stopPropagation()} onclick={event=>{event.stopPropagation();attempt++;}}>重试缩略图</button>{/if}</div>
<style>.asset-tile-container{position:relative;width:100%;height:100%}.tile-retry{position:absolute;bottom:28px;left:50%;transform:translateX(-50%);max-width:calc(100% - 12px);padding:4px 8px;border:1px solid var(--border);background:var(--bg-elev);color:var(--text);font:12px system-ui,sans-serif;border-radius:4px}.asset-tile{position:relative;display:flex;flex-direction:column;gap:8px;width:100%;height:100%;padding:6px;min-width:0;background:var(--bg-elev);border:2px solid transparent;border-radius:8px;color:var(--text);cursor:pointer;font:12px system-ui,sans-serif;text-align:left;box-sizing:border-box}.asset-tile.selected{border-color:var(--accent);background:var(--accent-soft)}.asset-tile:hover{background:var(--bg-sunken)}.asset-tile:active{background:var(--accent-soft)}.asset-tile:focus-visible{outline:2px solid var(--focus);outline-offset:1px}.asset-image{position:relative;min-height:0;width:100%;flex:1;overflow:hidden;border-radius:4px;background-color:var(--checker-a);background-image:linear-gradient(45deg,var(--checker-b) 25%,transparent 25%),linear-gradient(-45deg,var(--checker-b) 25%,transparent 25%),linear-gradient(45deg,transparent 75%,var(--checker-b) 75%),linear-gradient(-45deg,transparent 75%,var(--checker-b) 75%);background-size:16px 16px;background-position:0 0,0 8px,8px -8px,-8px 0}.asset-image img{width:100%;height:100%;object-fit:contain;display:block}.tile-name{width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;line-height:16px}.tile-status,.tile-versions,.tile-tags{position:absolute;display:flex;align-items:center;gap:4px;padding:3px;border-radius:4px;background:var(--bg-elev);font-size:11px}.tile-status{top:4px;left:4px}.tile-status.failed{color:var(--danger)}.tile-status :global(svg){animation:tile-spin 1s linear infinite}.tile-status.failed :global(svg){animation:none}.tile-versions{top:4px;right:4px}.tile-tags{bottom:4px;left:4px}.tile-tags:empty{display:none}.tile-loading{display:block;width:100%;height:100%;background:var(--bg-sunken)}.tile-error{display:flex;flex-direction:column;align-items:center;justify-content:center;height:100%;gap:8px;font-size:11px;color:var(--danger)}.asset-tile.list{flex-direction:row;align-items:center;gap:12px}.asset-tile.list .asset-image{width:44px;height:36px;flex:none}.asset-tile.list .tile-name{flex:1;width:auto}.asset-tile small{font-size:11px;color:var(--text-dim);white-space:nowrap}@keyframes tile-spin{to{transform:rotate(360deg)}}@media(prefers-reduced-motion:reduce){.tile-status :global(svg){animation:none}}</style>
